// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/proxy/Clones.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

interface ITokenImplementation {
    function initialize(string memory name_, string memory symbol_, address owner_, uint256 initialSupply) external;
    function mint(address to, uint256 amount) external;
}

contract TokenFactory is Ownable {
    using Clones for address;

    address public implementation;
    event TokenCreated(address indexed tokenAddress, string name, string symbol, uint256 initialSupply);

    constructor(address _implementation) Ownable(msg.sender) {
        require(_implementation != address(0), "impl 0");
        implementation = _implementation;
    }

    /// @notice Create a clone and initialize it, specifying owner of the token (owner_ will receive initialSupply)
    function createTokenDeterministic(
        string memory name_,
        string memory symbol_,
        uint256 initialSupply,
        address owner_,
        bytes32 salt
    ) external onlyOwner returns (address) {
        address clone = Clones.cloneDeterministic(implementation, salt);
        ITokenImplementation(clone).initialize(name_, symbol_, owner_, initialSupply);
        emit TokenCreated(clone, name_, symbol_, initialSupply);
        return clone;
    }

    /// @notice Create a clone and initialize it, specifying owner of the token (owner_ will receive initialSupply)
    function createToken(
        string memory name_,
        string memory symbol_,
        uint256 initialSupply,
        address owner_
    ) external onlyOwner returns (address) {
        address clone = Clones.clone(implementation);
        ITokenImplementation(clone).initialize(name_, symbol_, owner_, initialSupply);
        emit TokenCreated(clone, name_, symbol_, initialSupply);
        return clone;
    }

    function predictAddress(bytes32 salt) external view returns (address) {
        return Clones.predictDeterministicAddress(implementation, salt, address(this));
    }
}
